#!/usr/bin/env python3
"""Regenerate test/support/test_font_bytes_web.dart from the pubspec fonts."""

import base64
import hashlib
import pathlib
import textwrap

FONTS = [
    "assets/fonts/Orbitron-Variable.ttf",
    "assets/fonts/IBMPlexMono-400.ttf",
    "assets/fonts/IBMPlexMono-500.ttf",
    "assets/fonts/IBMPlexMono-600.ttf",
]
TARGET = pathlib.Path("test/support/test_font_bytes_web.dart")

lines = [
    "// Generated by test/support/generate_web_test_fonts.py. Do not edit.",
    "//",
    "// Chrome widget tests cannot read dart:io files or app assets, so the",
    "// exact pubspec font bytes are embedded here for the web implementation",
    "// of loadProductionTestFonts().",
    "",
    "import 'dart:convert';",
    "",
    "import 'package:flutter/services.dart' show ByteData;",
    "",
    "const Map<String, String> _fonts = {",
]
for path in FONTS:
    data = pathlib.Path(path).read_bytes()
    encoded = base64.b64encode(data).decode("ascii")
    digest = hashlib.sha256(data).hexdigest()
    lines.append(f"  '{path}': // sha256 {digest}")
    chunks = textwrap.wrap(encoded, 100)
    lines.append("      '" + chunks[0] + "'")
    for chunk in chunks[1:]:
        lines.append("      '" + chunk + "'")
    lines[-1] += ","
lines.extend(
    [
        "};",
        "",
        "Future<ByteData?> loadFontAsset(String path) async {",
        "  final encoded = _fonts[path];",
        "  if (encoded == null) return null;",
        "  return ByteData.sublistView(base64Decode(encoded));",
        "}",
        "",
    ]
)
TARGET.write_text("\n".join(lines))
print(f"wrote {TARGET}")
